#### P1473 \[USACO2.3\] 零的数列 Zero Sum
```cpp
bool isZero(string signals, vector<int> numbers) {
	int result	= 0;
	int op		= '+';
	int current = numbers[0];

	for(int i = 0; i < signals.size(); i++) {
		if(signals[i] == ' ') {
			current = current * 10 + numbers[i + 1];
		} else {
			if(op == '+')
				result += current;
			else
				result -= current;

			current = numbers[i + 1];
			op		= signals[i];
		}
	}

	if(op == '+')
		result += current;
	else
		result -= current;

	return result == 0;
}

string combine(string& signals, vector<int>& numbers) {
	string combine;
	for(int i = 0; i < numbers.size() + signals.size(); i++) {
		if(i % 2 == 0)
			combine += to_string(numbers[i / 2]);
		else
			combine += signals[i / 2];
	}
	return combine;
}

void dfs(string& signals, vector<int>& numbers, vector<string>& ans, int level, int limit) {
	if(level == limit - 1) {
		if(isZero(signals, numbers)) {
			ans.push_back(combine(signals, numbers));
		}
	} else {
		signals.push_back('+');
		dfs(signals, numbers, ans, level + 1, limit);
		signals.back() = ' ';
		dfs(signals, numbers, ans, level + 1, limit);
		signals.back() = '-';
		dfs(signals, numbers, ans, level + 1, limit);
		signals.pop_back();
	}
}

int main() {
	int limit;
	cin >> limit;
	vector<int>	   numbers(limit);
	vector<string> ans;
	iota(numbers.begin(), numbers.end(), 1);
	string signals;
	dfs(signals, numbers, ans, 0, limit);
	sort(ans.begin(), ans.end());
	for(const auto& item : ans) {
		cout << item << endl;
	}
}
```
